import csv
from collections import defaultdict, Counter

rows = []
with open('/app/benchmark/data.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        rows.append(row)

def split_composers(s):
    return [c.strip() for c in s.split(',')]

film_composer_map = [(int(r['Year']), r['Film'].strip(), split_composers(r['Composer'])) for r in rows]

composer_first_win_year = {}
repeat_ceremonies = 0

for year, film, composers in film_composer_map:
    is_repeat = False
    for c in composers:
        if c in composer_first_win_year and composer_first_win_year[c] < year:
            is_repeat = True
            break
    if is_repeat:
        repeat_ceremonies += 1
        print(f'  REPEAT: {year} - {film} - {composers} (because {[c for c in composers if c in composer_first_win_year and composer_first_win_year[c] < year]} already won)')
    else:
        print(f'  FIRST:  {year} - {film} - {composers}')
    for c in composers:
